from __future__ import absolute_import
from taf.selenium.sbts.pages import configuration
from taf.selenium.sbts.pages.v26r1.modals import ConfigurationResetModal


class ConfigurationResetPage(configuration.configuration_reset.ConfigurationResetPage):

    _CONFIG_RESET_BUTTON_XPATH = '//button[.//span[text()="Execute Reset"]]'

    def perform_config_reset(self, timeout=60):
        self._view_panel.click_config_reset(self._CONFIG_RESET_BUTTON_XPATH, timeout)
        configurtion_reset_modal = ConfigurationResetModal(self._driver)
        configurtion_reset_modal.wait_until_reset_modal_appear(timeout)
        configurtion_reset_modal.confirm()
        return self._view_panel.get_reset_status(timeout)
